{
  "tools": [
    {
      "name": "load_cohort",
      "description": "Load a cohort CSV file, auto-detect static/dynamic mode, and return summary statistics (size, columns, date range, geographic coverage).",
      "input_schema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Path to the CSV file"
          }
        },
        "required": [
          "path"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "plan_exposure",
      "description": "Return a no-download OpenAQ workload plan for the loaded static cohort. Call this before requesting researcher approval for an exposure run.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "enum": [
              "pm25",
              "pm10",
              "no2",
              "o3",
              "so2",
              "co"
            ]
          },
          "country": {
            "type": "string",
            "description": "ISO alpha-2 country code (default: us)."
          },
          "n_stations": {
            "type": "integer",
            "minimum": 1
          },
          "temporal_resolution": {
            "type": "string",
            "enum": [
              "daily",
              "hourly"
            ]
          },
          "location_strategy": {
            "type": "string",
            "enum": [
              "auto",
              "per_subject",
              "catalog"
            ]
          },
          "search_radius_km": {
            "type": "number",
            "exclusiveMinimum": 0,
            "maximum": 200
          }
        },
        "required": [
          "pollutant"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "estimate_exposure",
      "description": "Run exposure estimation for the loaded cohort. For static mode, specify a pollutant (pm25, pm10, no2, o3, so2, co, or 'all'). For dynamic mode, specify the backend (gmaps or xgb). Supports IDW multi-station averaging, outlier detection, and completeness QC for static mode.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "description": "Pollutant to estimate (static mode). One of: pm25, pm10, no2, o3, so2, co, or 'all'"
          },
          "backend": {
            "type": "string",
            "description": "Dynamic mode backend: 'gmaps' (default) or 'xgb'",
            "enum": [
              "gmaps",
              "xgb"
            ]
          },
          "country": {
            "type": "string",
            "description": "ISO country code for geocoding (default: 'us')"
          },
          "n_stations": {
            "type": "integer",
            "description": "Number of stations for IDW averaging (default: 1, nearest only)"
          },
          "outlier_detection": {
            "type": "boolean",
            "description": "Enable IQR outlier removal before computing metrics (default: false)"
          },
          "min_completeness": {
            "type": "number",
            "description": "Minimum completeness percentage (0-100) for QC flagging"
          },
          "temporal_resolution": {
            "type": "string",
            "enum": [
              "daily",
              "hourly"
            ],
            "description": "OpenAQ retrieval resolution. Use daily for daily health analyses to reduce API volume; hourly is retained for sub-daily analyses."
          },
          "location_strategy": {
            "type": "string",
            "enum": [
              "auto",
              "per_subject",
              "catalog"
            ],
            "description": "Station-discovery strategy. Auto can use a cached country catalog for large single-country cohorts and otherwise uses per-subject queries."
          },
          "search_radius_km": {
            "type": "number",
            "exclusiveMinimum": 0,
            "maximum": 200,
            "description": "Maximum city-to-monitor search distance in kilometres."
          },
          "approved_plan_id": {
            "type": "string",
            "description": "Immutable plan identifier approved by the researcher in interactive mode."
          }
        }
      },
      "requires_researcher_approval": true
    },
    {
      "name": "approve_exposure_plan",
      "description": "Bind explicit researcher approval to one immutable exposure plan.",
      "input_schema": {
        "type": "object",
        "properties": {
          "plan_id": {
            "type": "string"
          },
          "researcher_approved": {
            "type": "boolean"
          }
        },
        "required": [
          "plan_id",
          "researcher_approved"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "estimate_boundary_exposure",
      "description": "Estimate an ambient pollutant record for an explicit administrative boundary. Use either a researcher-supplied GeoJSON file or geoBoundaries ISO3/ADM selection. The result is an unweighted mean of monitor-level means within the polygon, with station coverage and boundary provenance.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "enum": [
              "pm25",
              "pm10",
              "no2",
              "o3",
              "so2",
              "co"
            ]
          },
          "start_date": {
            "type": "string",
            "description": "Inclusive ISO date."
          },
          "end_date": {
            "type": "string",
            "description": "Inclusive ISO date."
          },
          "iso3": {
            "type": "string",
            "description": "ISO-3166 alpha-3 country code for geoBoundaries."
          },
          "adm_level": {
            "type": "integer",
            "minimum": 0,
            "maximum": 5
          },
          "boundary_name": {
            "type": "string",
            "description": "Administrative unit name or GeoJSON feature name."
          },
          "boundary_geojson_path": {
            "type": "string",
            "description": "Local GeoJSON path; preferred for a study-specific boundary."
          },
          "min_completeness": {
            "type": "number",
            "minimum": 0,
            "maximum": 100
          },
          "temporal_resolution": {
            "type": "string",
            "enum": [
              "daily",
              "hourly"
            ],
            "description": "OpenAQ retrieval resolution. Use daily when the health outcome and intended analysis are daily."
          },
          "researcher_approved": {
            "type": "boolean"
          }
        },
        "required": [
          "pollutant",
          "start_date",
          "end_date"
        ]
      },
      "requires_researcher_approval": true
    },
    {
      "name": "estimate_boundary_exposure_batch",
      "description": "Estimate one pollutant for every selected feature in a boundary GeoJSON. Uses deterministic ordering, atomic per-unit checkpoints, and combined daily output. In self-driving mode, use deterministic chunks of at most 5 named boundaries.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "enum": [
              "pm25",
              "pm10",
              "no2",
              "o3",
              "so2",
              "co"
            ]
          },
          "start_date": {
            "type": "string"
          },
          "end_date": {
            "type": "string"
          },
          "boundary_geojson_path": {
            "type": "string"
          },
          "boundary_names": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "min_completeness": {
            "type": "number",
            "minimum": 0,
            "maximum": 100
          },
          "temporal_resolution": {
            "type": "string",
            "enum": [
              "daily",
              "hourly"
            ]
          },
          "checkpoint_path": {
            "type": "string"
          },
          "max_stations": {
            "type": "integer",
            "minimum": 1
          },
          "researcher_approved": {
            "type": "boolean"
          }
        },
        "required": [
          "pollutant",
          "start_date",
          "end_date",
          "boundary_geojson_path"
        ]
      },
      "requires_researcher_approval": true
    },
    {
      "name": "get_exposure_summary",
      "description": "Get summary statistics for the current exposure results: mean, SD, range, n with data, distance distribution.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "description": "Which pollutant results to summarize (defaults to first available)"
          }
        }
      },
      "requires_researcher_approval": false
    },
    {
      "name": "get_raw_data",
      "description": "Get raw hourly air quality measurements. A subject_id is required for point exposure and omitted for an administrative-boundary record.",
      "input_schema": {
        "type": "object",
        "properties": {
          "subject_id": {
            "type": "string",
            "description": "The subject identifier"
          },
          "pollutant": {
            "type": "string",
            "description": "Pollutant (defaults to first available)"
          }
        }
      },
      "requires_researcher_approval": false
    },
    {
      "name": "get_daily_data",
      "description": "Get daily aggregated air quality data. A subject_id is required for point exposure and omitted for an administrative-boundary record.",
      "input_schema": {
        "type": "object",
        "properties": {
          "subject_id": {
            "type": "string",
            "description": "The subject identifier"
          },
          "pollutant": {
            "type": "string",
            "description": "Pollutant (defaults to first available)"
          }
        }
      },
      "requires_researcher_approval": false
    },
    {
      "name": "compare_metrics",
      "description": "Compare exposure metrics (mean, median, p75, p95) across pollutants or between different estimation approaches.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutants": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "List of pollutants to compare (defaults to all available)"
          }
        }
      },
      "requires_researcher_approval": false
    },
    {
      "name": "convert_to_aqi",
      "description": "Convert a pollutant concentration to EPA AQI value and category.",
      "input_schema": {
        "type": "object",
        "properties": {
          "pollutant": {
            "type": "string",
            "description": "One of: pm25, pm10, no2, o3, so2, co"
          },
          "concentration": {
            "type": "number",
            "description": "Concentration value to convert"
          }
        },
        "required": [
          "pollutant",
          "concentration"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "get_accuweather_air_quality",
      "description": "Retrieve AccuWeather's current/forecast air-quality index, category, and dominant-pollutant information for a coordinate. The response is a provider index and must not be used as a pollutant concentration.",
      "input_schema": {
        "type": "object",
        "properties": {
          "latitude": {
            "type": "number"
          },
          "longitude": {
            "type": "number"
          }
        },
        "required": [
          "latitude",
          "longitude"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "export_results",
      "description": "Export exposure results to a file. Supports CSV, GeoJSON, and long-format tidy CSV.",
      "input_schema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Output file path"
          },
          "format": {
            "type": "string",
            "enum": [
              "csv",
              "geojson",
              "long_format"
            ],
            "description": "Export format (default: csv)"
          },
          "pollutant": {
            "type": "string",
            "description": "Which pollutant results to export (defaults to first available)"
          }
        },
        "required": [
          "path"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "get_station_info",
      "description": "Get monitoring station metadata for the exposure results. Static mode only.",
      "input_schema": {
        "type": "object",
        "properties": {
          "subject_id": {
            "type": "string",
            "description": "Optional: filter to a specific subject"
          }
        }
      },
      "requires_researcher_approval": false
    },
    {
      "name": "web_search",
      "description": "Search the web for scientific literature, exposure guidelines, or methodological references.",
      "input_schema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search query (e.g., 'PM2.5 childhood asthma epidemiology')"
          },
          "num_results": {
            "type": "integer",
            "description": "Number of results to return (default 5, max 10)"
          }
        },
        "required": [
          "query"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "get_decision_log",
      "description": "Return the current analytical decision log.",
      "input_schema": {
        "type": "object",
        "properties": {}
      },
      "requires_researcher_approval": false
    },
    {
      "name": "lock_reanalysis_invariants",
      "description": "Lock only the scientific invariants and safety bounds for a self-driving reanalysis; leave retrieval and implementation choices open.",
      "input_schema": {
        "type": "object",
        "properties": {
          "study_id": {
            "type": "string"
          },
          "research_question": {
            "type": "string"
          },
          "target_outcome_and_population": {
            "type": "string"
          },
          "pollutants": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "principal_contrast": {
            "type": "string"
          },
          "principal_variants": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "string"
            },
            "description": "The explicit fitted comparison selected as the reanalysis target. Ordinarily provide one label anchored to a table, figure, model, or results sentence. Include another variant only when it forms part of the same prespecified target and will receive its own fitted result."
          },
          "broad_geography": {
            "type": "string"
          },
          "target_geographic_units": {
            "type": [
              "integer",
              "null"
            ],
            "minimum": 1,
            "description": "Article-reported count of geographic units, when stated. Leave null when the article gives no count."
          },
          "target_geographic_unit_type": {
            "type": [
              "string",
              "null"
            ],
            "description": "Article-reported unit type, such as county or municipality."
          },
          "start_date": {
            "type": "string"
          },
          "end_date": {
            "type": "string"
          },
          "prohibited_evidence": {
            "type": "array",
