                },
                "finding": {
                  "type": "string",
                  "description": "Scientific specification supported by the artifact."
                }
              },
              "required": [
                "artifact",
                "finding"
              ],
              "additionalProperties": false
            }
          },
          "article_evidence_map": {
            "type": "object",
            "description": "Optional structured notes from article inspection. This is evidence, not a compliance checklist, and may be partial when full text is unavailable."
