          },
          "scientific_justification": {
            "type": "string"
          },
          "fidelity_impact": {
            "type": "string",
            "enum": [
              "none",
              "source_substitution",
              "coverage_subset",
              "covariate_omission",
              "construct_change",
              "supported_sensitivity"
            ]
          },
          "agreement_independent": {
            "type": "boolean"
          }
        },
        "required": [
          "changed_dimensions",
          "evidence",
          "scientific_justification",
          "fidelity_impact",
          "agreement_independent"
        ]
      },
      "requires_researcher_approval": false
    },
    {
      "name": "record_reanalysis_fidelity",
      "description": "Persist the fidelity class, deviations, and evidence for a completed or stopped reanalysis.",
