            "type": "string",
            "enum": [
              "matched_fit",
              "source_substitution_fit",
              "reduced_coverage_fit",
              "reduced_adjustment_fit",
              "bounded_fit",
              "supported_sensitivity_fit",
              "bounded_proxy_fit",
              "unsupported_fit",
              "evidenced_stop"
            ]
          },
          "status": {
            "type": "string",
            "enum": [
              "fitted",
              "stopped"
